SELECT manager_name, district
FROM shop
WHERE shop_id IN (
    SELECT shop_id
    FROM shop
    WHERE number_products = (
        SELECT MAX(number_products)
        FROM shop
    )
);

SELECT district FROM shop WHERE number_products < 3000 GROUP BY district
INTERSECT
SELECT district FROM shop WHERE number_products > 10000 GROUP BY district;

SELECT template_id, COUNT(*) as usage_count
